INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DHCPv6 die einzige Methode für automatische Adresszuweisung in IPv6?', 2, '[{"text": "Nein", "correct": true, "because": "SLAAC existiert auch"}, {"text": "Ja", "correct": false, "because": "Alternativen verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Phasen hat der DHCPv6-Prozess typischerweise?', 3, '[{"text": "4", "correct": true, "because": "Solicit, Advertise, Request, Reply"}, {"text": "2", "correct": false, "because": "Zu wenig"}, {"text": "6", "correct": false, "because": "Zu viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt DHCPv6 in IPv6-Netzwerken?', 4, '[{"text": "Automatische Adresszuweisung", "correct": true, "because": "Vergibt IPs zentral"}, {"text": "Routing-Optimierung", "correct": false, "because": "Nicht primäre Funktion"}, {"text": "Subnetzsegmentierung", "correct": false, "because": "Netzwerkdesign-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPv6 vergibt Adressen dynamisch. b) Es ersetzt SLAAC komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, ergänzt SLAAC"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DHCPv6?', 5, '[{"text": "Manuelle Adressvergabe", "correct": true, "because": "Automatisierung ist Ziel"}, {"text": "Client-Anfrage", "correct": false, "because": "Teil des Prozesses"}, {"text": "Server-Konfiguration", "correct": false, "because": "Notwendig für Zuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 auch DNS-Informationen liefert?', 2, '[{"text": "Ja", "correct": true, "because": "Optionale Konfiguration"}, {"text": "Nein", "correct": false, "because": "Funktion verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht startet den DHCPv6-Prozess?', 3, '[{"text": "Solicit", "correct": true, "because": "Client sucht Server"}, {"text": "Advertise", "correct": false, "because": "Antwort des Servers"}, {"text": "Reply", "correct": false, "because": "Letzte Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet DHCPv6?', 5, '[{"text": "Adresszuweisung", "correct": true, "because": "Hauptzweck"}, {"text": "Netzwerkkonfiguration", "correct": true, "because": "z. B. DNS-Server"}, {"text": "Routing-Tabellen", "correct": false, "because": "Nicht primäre Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DHCPv6 benötigt einen Server. b) Es funktioniert ohne Router. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Server nötig, b) unabhängig vom Router"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DHCPv6?', 4, '[{"text": "DHCP-Server", "correct": false, "because": "Zentrale Komponente"}, {"text": "Client-Anfrage", "correct": false, "because": "Startet Prozess"}, {"text": "Statische IPs", "correct": true, "because": "Dynamisch ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt DHCPv6 die manuelle Konfiguration?', 2, '[{"text": "Nein", "correct": true, "because": "Option, nicht Pflicht"}, {"text": "Ja", "correct": false, "because": "Manuell bleibt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei DHCPv6 essenziell?', 4, '[{"text": "Client", "correct": true, "because": "Startet Anfrage"}, {"text": "Server", "correct": true, "because": "Vergibt Adressen"}, {"text": "Router", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DHCPv6 wie DHCPv4 funktioniert. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Ähnlicher Prozess"}, {"text": "Nein", "correct": false, "because": "Anpassungen für IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DHCPv6?', 3, '[{"text": "Zentrale Verwaltung", "correct": true, "because": "Effiziente Zuweisung"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Automatisierung ist Ziel"}, {"text": "Subnetzgröße", "correct": false, "because": "Netzwerkdesign-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPv6 nutzt Solicit-Reply. b) Es ist für kleine Netze ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, flexibel nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCPv6?', 5, '[{"text": "Dynamische Zuweisung", "correct": true, "because": "Automatisiert IPs"}, {"text": "Zusätzliche Konfiguration", "correct": true, "because": "z. B. DNS"}, {"text": "Statische Adressen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DHCPv6 unwichtig?', 3, '[{"text": "Server-Antwort", "correct": false, "because": "Teil des Prozesses"}, {"text": "Client-Anfrage", "correct": false, "because": "Initiert Zuweisung"}, {"text": "Manuelle Host-Liste", "correct": true, "because": "Dynamisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Funktioniert DHCPv6 ohne Server?', 2, '[{"text": "Nein", "correct": true, "because": "Server ist essenziell"}, {"text": "Ja", "correct": false, "because": "Zentraler Punkt nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 Adressen dauerhaft vergibt?', 3, '[{"text": "Nein", "correct": true, "because": "Lease-Zeiten üblich"}, {"text": "Ja", "correct": false, "because": "Dynamisch, nicht fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase bestätigt die Adresszuweisung in DHCPv6?', 4, '[{"text": "Reply", "correct": true, "because": "Abschluss des Prozesses"}, {"text": "Request", "correct": false, "because": "Anfrage des Clients"}, {"text": "Advertise", "correct": false, "because": "Angebot des Servers"}]');
